'use client';

import { useState, useEffect } from 'react';
import { ChevronLeft, RefreshCw, Server, Building2, Router, Settings } from 'lucide-react';
import Link from 'next/link';
import { Button } from '@/back-end/components/ui/button';

interface ConsoleData {
  id: string;
  name: string;
  type: string;
  status: string;
  organizationId?: string;
  organizationName?: string;
}

interface SiteData {
  id: string;
  name: string;
  description?: string;
  consoleId?: string;
  consoleName?: string;
  deviceCount?: number;
}

interface DeviceData {
  id: string;
  name: string;
  type: string;
  mac: string;
  ip?: string;
  status: string;
  siteId?: string;
  siteName?: string;
  model?: string;
  firmware?: string;
}

interface UnifiConfigItem {
  id: string;
  type: string;
  apiKey: string | null;
  apiKeyFull?: string;
  isActive: boolean;
  createdAt: string;
  updatedAt: string;
}

export default function MonitorPatrimoniosPage() {
  const [apiKey, setApiKey] = useState('');
  const [loading, setLoading] = useState(false);
  const [consoles, setConsoles] = useState<ConsoleData[]>([]);
  const [sites, setSites] = useState<SiteData[]>([]);
  const [devices, setDevices] = useState<DeviceData[]>([]);
  const [activeTab, setActiveTab] = useState<'consoles' | 'sites' | 'devices'>('consoles');
  const [error, setError] = useState('');
  const [savedKeys, setSavedKeys] = useState<UnifiConfigItem[]>([]);
  const [loadingKeys, setLoadingKeys] = useState(false);
  const [showSavedKeys, setShowSavedKeys] = useState(false);
  const [successMessage, setSuccessMessage] = useState('');

  useEffect(() => {
    loadSavedApiKey();
  }, []);

  const loadSavedApiKey = async () => {
    try {
      const response = await fetch('/api/unifi-config');
      const data = await response.json();
      if (data.config?.apiKey) {
        setApiKey(data.config.apiKey);
      }
    } catch (error) {
      console.error('Erro ao carregar API Key:', error);
    }
    
    // Carregar também todas as chaves salvas
    loadAllSavedKeys();
  };

  const loadAllSavedKeys = async () => {
    setLoadingKeys(true);
    try {
      const response = await fetch('/api/unifi-config?all=true');
      const data = await response.json();
      setSavedKeys(data.configs || []);
    } catch (error) {
      console.error('Erro ao carregar chaves salvas:', error);
    } finally {
      setLoadingKeys(false);
    }
  };

  const handleUseKey = (keyItem: UnifiConfigItem) => {
    if (keyItem.apiKeyFull) {
      setApiKey(keyItem.apiKeyFull);
      setShowSavedKeys(false);
    }
  };

  const handleDeactivateKey = async (id: string) => {
    if (!confirm('Deseja desativar esta chave de API?')) return;

    try {
      const response = await fetch(`/api/unifi-config?id=${id}`, {
        method: 'DELETE',
      });

      if (response.ok) {
        loadAllSavedKeys();
        setSuccessMessage('Chave desativada com sucesso');
        setTimeout(() => setSuccessMessage(''), 3000);
      }
    } catch (error) {
      setError('Erro ao desativar chave');
    }
  };

  const loadData = async () => {
    if (!apiKey) {
      setError('API Key não configurada. Salve a configuração primeiro.');
      return;
    }

    setLoading(true);
    setError('');

    try {
      // Buscar consoles
      const consolesRes = await fetch('/api/monitor-patrimonios/consoles', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ apiKey }),
      });
      const consolesData = await consolesRes.json();
      setConsoles(consolesData.consoles || []);

      // Buscar sites
      const sitesRes = await fetch('/api/monitor-patrimonios/sites', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ apiKey }),
      });
      const sitesData = await sitesRes.json();
      setSites(sitesData.sites || []);

      // Buscar devices
      const devicesRes = await fetch('/api/monitor-patrimonios/devices', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ apiKey }),
      });
      const devicesData = await devicesRes.json();
      setDevices(devicesData.devices || []);
    } catch (error) {
      console.error('Erro ao carregar dados:', error);
      setError('Erro ao buscar dados da API Ubiquiti');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-background min-h-screen py-6">
      <div className="max-w-7xl mx-auto px-4">
        {/* Header */}
        <div className="form-title-sticky flex items-center justify-between mb-6">
          <div className="flex items-center">
            <Link href="/unifi-config" className="mr-4">
              <ChevronLeft className="h-6 w-6 text-primary hover:text-primary/80 transition" />
            </Link>
            <div>
              <h1 className="text-h3 font-bold">Monitor de Rede Ubiquiti</h1>
              <p className="text-gray-600 text-sm mt-1">Configuração e monitoramento da rede Ubiquiti</p>
            </div>
          </div>
          
          <Link href="/unifi-config">
            <Button variant="outline" className="flex items-center gap-2">
              <Settings className="h-4 w-4" />
              Configurar UniFi
            </Button>
          </Link>
        </div>

        <div className="bg-white rounded-lg shadow-lg p-8 space-y-6">
          {/* Card de API Key */}
          <div className="border-b pb-6">
            <div className="flex items-center gap-4 mb-4">
            <div className="flex-1">
              <label className="block text-sm font-medium mb-2">API Key</label>
              <input
                type="password"
                value={apiKey}
                onChange={(e) => setApiKey(e.target.value)}
                className="w-full px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-primary"
                placeholder="Sua API Key da Ubiquiti"
              />
            </div>
            <Button
              onClick={loadData}
              disabled={loading || !apiKey}
              className="flex items-center gap-2 bg-primary hover:bg-primary/90"
            >
              <RefreshCw className={`h-5 w-5 ${loading ? 'animate-spin' : ''}`} />
              {loading ? 'Carregando...' : 'Buscar Dados'}
            </Button>
          </div>

          {error && (
            <div className="p-4 bg-red-100 border border-red-400 text-red-700 rounded mb-4">
              {error}
            </div>
          )}
          {successMessage && (
            <div className="p-4 bg-green-100 border border-green-400 text-green-700 rounded mb-4">
              {successMessage}
            </div>
          )}

          {/* Botão para ver chaves salvas */}
          <div className="mt-4">
            <button
              onClick={() => setShowSavedKeys(true)}
              className="text-blue-500 hover:text-blue-700 text-sm flex items-center gap-1"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
              </svg>
              Ver chaves de API cadastradas
            </button>
          </div>

          {/* Lista de chaves salvas */}
          {showSavedKeys && (
            <div className="mt-4 border rounded-lg p-4 bg-gray-50">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-lg font-bold">Chaves de API Cadastradas</h3>
                <button
                  onClick={() => setShowSavedKeys(false)}
                  className="text-gray-500 hover:text-gray-700"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              </div>
              
              {loadingKeys ? (
                <p className="text-gray-500">Carregando...</p>
              ) : savedKeys.length > 0 ? (
                <div className="overflow-x-auto">
                  <table className="w-full border-collapse">
                    <thead>
                      <tr className="bg-gray-100 border-b">
                        <th className="px-4 py-2 text-left font-medium text-gray-700">API Key</th>
                        <th className="px-4 py-2 text-left font-medium text-gray-700">Status</th>
                        <th className="px-4 py-2 text-left font-medium text-gray-700">Criada em</th>
                        <th className="px-4 py-2 text-left font-medium text-gray-700">Ações</th>
                      </tr>
                    </thead>
                    <tbody>
                      {savedKeys.map((key) => (
                        <tr key={key.id} className="border-b hover:bg-gray-50">
                          <td className="px-4 py-2 font-mono text-sm">{key.apiKey || 'N/A'}</td>
                          <td className="px-4 py-2">
                            <span className={`px-2 py-1 rounded text-sm ${
                              key.isActive ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-700'
                            }`}>
                              {key.isActive ? 'Ativa' : 'Inativa'}
                            </span>
                          </td>
                          <td className="px-4 py-2 text-sm text-gray-600">
                            {new Date(key.createdAt).toLocaleDateString('pt-BR')}
                          </td>
                          <td className="px-4 py-2">
                            <div className="flex gap-2">
                              <button
                                onClick={() => handleUseKey(key)}
                                className="text-blue-500 hover:text-blue-700 text-sm font-medium"
                              >
                                Usar no Monitor
                              </button>
                              {key.isActive && (
                                <button
                                  onClick={() => handleDeactivateKey(key.id)}
                                  className="text-red-500 hover:text-red-700 text-sm font-medium"
                                >
                                  Desativar
                                </button>
                              )}
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              ) : (
                <p className="text-gray-500">Nenhuma chave de API cadastrada.</p>
              )}
            </div>
          )}
          </div>

          {/* Tabs */}
          <div>
            <div className="flex border-b">
            <button
              onClick={() => setActiveTab('consoles')}
              className={`flex items-center gap-2 px-6 py-4 font-medium transition-colors ${
                activeTab === 'consoles'
                  ? 'border-b-2 border-primary text-primary'
                  : 'text-gray-500 hover:text-gray-700'
              }`}
            >
              <Server className="h-5 w-5" />
              Consoles ({consoles.length})
            </button>
            <button
              onClick={() => setActiveTab('sites')}
              className={`flex items-center gap-2 px-6 py-4 font-medium transition-colors ${
                activeTab === 'sites'
                  ? 'border-b-2 border-primary text-primary'
                  : 'text-gray-500 hover:text-gray-700'
              }`}
            >
              <Building2 className="h-5 w-5" />
              Sites ({sites.length})
            </button>
            <button
              onClick={() => setActiveTab('devices')}
              className={`flex items-center gap-2 px-6 py-4 font-medium transition-colors ${
                activeTab === 'devices'
                  ? 'border-b-2 border-primary text-primary'
                  : 'text-gray-500 hover:text-gray-700'
              }`}
            >
              <Router className="h-5 w-5" />
              Devices ({devices.length})
            </button>
          </div>

          {/* Conteúdo das Tabs */}
          <div className="p-6">
            {activeTab === 'consoles' && (
              <div>
                {consoles.length === 0 ? (
                  <p className="text-gray-500 text-center py-8">Nenhum console encontrado. Clique em "Buscar Dados" para carregar.</p>
                ) : (
                  <div className="overflow-x-auto">
                    <table className="w-full border-collapse">
                      <thead>
                        <tr className="bg-gray-100 border-b">
                          <th className="px-4 py-3 text-left font-medium text-gray-700">Nome</th>
                          <th className="px-4 py-3 text-left font-medium text-gray-700">Tipo</th>
                          <th className="px-4 py-3 text-left font-medium text-gray-700">Status</th>
                          <th className="px-4 py-3 text-left font-medium text-gray-700">Organização</th>
                          <th className="px-4 py-3 text-left font-medium text-gray-700">ID</th>
                        </tr>
                      </thead>
                      <tbody>
                        {consoles.map((console) => (
                          <tr key={console.id} className="border-b hover:bg-gray-50">
                            <td className="px-4 py-3 font-medium">{console.name}</td>
                            <td className="px-4 py-3">{console.type}</td>
                            <td className="px-4 py-3">
                              <span className={`px-2 py-1 rounded text-sm ${
                                console.status === 'Online' ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-700'
                              }`}>
                                {console.status}
                              </span>
                            </td>
                            <td className="px-4 py-3 text-gray-600">{console.organizationName || '-'}</td>
                            <td className="px-4 py-3 text-sm text-gray-500 font-mono">{console.id}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>
            )}

            {activeTab === 'sites' && (
              <div>
                {sites.length === 0 ? (
                  <p className="text-gray-500 text-center py-8">Nenhum site encontrado. Clique em "Buscar Dados" para carregar.</p>
                ) : (
                  <div className="overflow-x-auto">
                    <table className="w-full border-collapse">
                      <thead>
                        <tr className="bg-gray-100 border-b">
                          <th className="px-4 py-3 text-left font-medium text-gray-700">Nome</th>
                          <th className="px-4 py-3 text-left font-medium text-gray-700">Descrição</th>
                          <th className="px-4 py-3 text-left font-medium text-gray-700">Console</th>
                          <th className="px-4 py-3 text-left font-medium text-gray-700">Devices</th>
                          <th className="px-4 py-3 text-left font-medium text-gray-700">ID</th>
                        </tr>
                      </thead>
                      <tbody>
                        {sites.map((site) => (
                          <tr key={site.id} className="border-b hover:bg-gray-50">
                            <td className="px-4 py-3 font-medium">{site.name}</td>
                            <td className="px-4 py-3 text-gray-600">{site.description || '-'}</td>
                            <td className="px-4 py-3 text-gray-600">{site.consoleName || '-'}</td>
                            <td className="px-4 py-3">
                              <span className="px-2 py-1 bg-blue-100 text-blue-700 rounded text-sm">
                                {site.deviceCount || 0} devices
                              </span>
                            </td>
                            <td className="px-4 py-3 text-sm text-gray-500 font-mono">{site.id}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>
            )}

            {activeTab === 'devices' && (
              <div>
                {devices.length === 0 ? (
                  <p className="text-gray-500 text-center py-8">Nenhum device encontrado. Clique em "Buscar Dados" para carregar.</p>
                ) : (
                  <div className="overflow-x-auto">
                    <table className="w-full border-collapse">
                      <thead>
                        <tr className="bg-gray-100 border-b">
                          <th className="px-4 py-3 text-left font-medium text-gray-700">Nome</th>
                          <th className="px-4 py-3 text-left font-medium text-gray-700">Tipo</th>
                          <th className="px-4 py-3 text-left font-medium text-gray-700">Modelo</th>
                          <th className="px-4 py-3 text-left font-medium text-gray-700">MAC</th>
                          <th className="px-4 py-3 text-left font-medium text-gray-700">IP</th>
                          <th className="px-4 py-3 text-left font-medium text-gray-700">Status</th>
                          <th className="px-4 py-3 text-left font-medium text-gray-700">Site</th>
                        </tr>
                      </thead>
                      <tbody>
                        {devices.map((device) => (
                          <tr key={device.id} className="border-b hover:bg-gray-50">
                            <td className="px-4 py-3 font-medium">{device.name}</td>
                            <td className="px-4 py-3">{device.type}</td>
                            <td className="px-4 py-3 text-gray-600">{device.model || '-'}</td>
                            <td className="px-4 py-3 text-sm font-mono text-gray-600">{device.mac}</td>
                            <td className="px-4 py-3 text-sm text-gray-600">{device.ip || '-'}</td>
                            <td className="px-4 py-3">
                              <span className={`px-2 py-1 rounded text-sm ${
                                device.status === 'Online' ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-700'
                              }`}>
                                {device.status}
                              </span>
                            </td>
                            <td className="px-4 py-3 text-gray-600">{device.siteName || '-'}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
    </div>
  );
}
